<?php require __DIR__.'/_init.php';require_admin();$statuses=['submitted','in_review','in_progress','completed','declined'];$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$new=$_POST['status']??'';if(!in_array($new,$statuses,true))$err='Invalid status.';else{$db=db();$db->beginTransaction();$q=$db->prepare('SELECT status FROM service_requests WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetchColumn();if($old===false){$db->rollBack();$err='Request not found.';}else{$db->prepare('UPDATE service_requests SET status=? WHERE id=?')->execute([$new,$id]);$db->prepare('INSERT INTO request_status_history(request_id,changed_by,old_status,new_status) VALUES(?,?,?,?)')->execute([$id,$_SESSION['user']['id'],$old,$new]);$db->commit();flash('Request status updated.');header('Location: /admin.php');exit;}}}$rows=db()->query('SELECT r.*,u.full_name,u.username FROM service_requests r JOIN users u ON u.id=r.user_id ORDER BY r.created_at DESC')->fetchAll();page_start('Request administration');?><div class="eyebrow">CAMPUSFLOW ADMIN</div><h1>Request queue</h1><?php if($err)echo '<p class="error">'.e($err).'</p>';?><div class="table-wrap"><table><tr><th>Student</th><th>Request</th><th>Tracking</th><th>Status</th><th>Update</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?><small>@<?=e($r['username'])?></small></td><td><?=e($r['title'])?><small><?=e($r['category'])?></small></td><td><?=e($r['tracking_id'])?></td><td><?=e($r['status'])?></td><td><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><?php foreach($statuses as $s)echo '<option'.($s===$r['status']?' selected':'').'>'.e($s).'</option>';?></select><button class="button small">Save</button></form></td></tr><?php endforeach;?></table></div><?php page_end();?>
